'use strict';
const fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {productionFunction}=require('./approval-ui-preview.cjs');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'public/financial-dashboard.html'),'utf8');
const units=[{id:'unit-qa',name:"Cabang O'Brien <Utama> "+'Nama panjang '.repeat(8),code:'QA',category:'LAUNDRY'}];
const staff=[{id:'employee-qa',name:"Karyawan O'Brien "+'Nama '.repeat(12),branch_id:'unit-qa',department:'Operasional',email:'qa@example.invalid',active:true,revision:4}];
function page(){
 const styles=[...html.matchAll(/<style\b[^>]*>[\s\S]*?<\/style>/g)].map(m=>m[0]).join('');
 const constants=['viewClusters','sectionGroups','rolePermissions'].map(n=>html.split(/\r?\n/).find(l=>l.startsWith('const '+n+'='))).join('\n');
 const functions=['escHtml','escapeHtml','pageHead','canAccess','navRoot','sectionNav','usersPage','branchesSystemPage','employeeDirectoryPage','companyPayrollPage','getArchivedDevices','setArchivedDevices','toggleArchiveDevice','bindManagement'].map(productionFunction).join('\n');
 return '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+styles+'<style>body{margin:0}#content{min-width:0;padding:24px;max-width:1500px;margin:auto}@media(max-width:600px){#content{padding:16px}}</style></head><body><main id="content"></main><script>'+fs.readFileSync(path.join(root,'public/lucide-icons.js'),'utf8')+'</script><script>let role="owner",view="users";const content=document.querySelector("#content"),icon=k=>SipekaIcons.render(k),branches='+JSON.stringify(units.map(u=>[u.name,u.code])).replace(/</g,'\\u003c')+';window.calls=[];window.SipekaUnits='+JSON.stringify(units).replace(/</g,'\\u003c')+';window.SipekaCompany={name:"Perusahaan QA",revision:2};window.SipekaCurrentUser={id:"owner-qa",role:"OWNER"};window.SipekaUi={message:e=>e.message};window.SipekaAuth={generation:()=>1,api:async(p,o)=>{calls.push({p,o});return p==="/api/operational-staff"?'+JSON.stringify(staff)+':{};},bootstrap:async()=>{}};window.SipekaAllUsersList=[{id:"device-qa",username:"device_qa",full_name:"Device Kasir "+"Label panjang ".repeat(12),role:"STAFF",branch_name:SipekaUnits[0].name}];window.SipekaCreateStaff=()=>calls.push("create-device");window.SipekaCreateBranch=()=>calls.push("create-branch");window.SipekaPromptRenameBranch=(...args)=>calls.push({rename:args});window.SipekaPromptArchiveBranch=(...args)=>calls.push({archive:args});window.showToast=()=>{};'+constants+functions+'window.SipekaToggleArchiveDevice=toggleArchiveDevice;</script><script>'+fs.readFileSync(path.join(root,'public/device-staff-ui.js'),'utf8')+'</script><script>'+fs.readFileSync(path.join(root,'public/employee-payroll-ui.js'),'utf8')+'</script><script>function show(key){view=key;content.innerHTML=sectionNav()+({users:usersPage,branchesSys:branchesSystemPage,employees:employeeDirectoryPage,companyPayroll:companyPayrollPage}[key])();bindManagement();content.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>show(b.dataset.view));}window.render=()=>show(view);window.__sipekaApplyState=()=>show(view);SipekaDeviceStaff.load(SipekaCurrentUser).then(()=>show("users"));</script></body></html>';
}
function createServer(){return http.createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(page());});}
module.exports={createServer,units};
